    has:pub name: str;
    has:protect medical_history: list[str] = [];
    has:priv owner_contact: str = "";

    def:protect add_record(r: str) {
        self.medical_history.append(r);
    }
}

obj VetRecord(PetRecord) {
    def:pub note(n: str) {
        # owner_contact is priv to PetRecord, so do not access it here
        self.add_record(n);
    }
}

with entry {
    vet = VetRecord(name="Fluffy");
    vet.note("Annual checkup");
}
```

