obj VetRecord(PetRecord) {
    def:pub note(n: str) {
        self.owner_contact = n;   // str -> str, allowed for protect
    }
}

with entry {
    vet = VetRecord(name="Fluffy");   // no owner_contact argument
    vet.note("Annual checkup");
}
```

